#[tokio::test]
async fn shows_no_hsbc_duplicates() {
    let app = start_app().await.unwrap();
    time::sleep(Duration::from_secs(2)).await;

    let known_duplicate = EntitySearchRequest::new_with_strictness("HSBC".into(), 10, 0.9).unwrap();
    let entities = search_entities(&app, &known_duplicate).await.unwrap();

    let mut duplicates: HashMap<String, usize> = HashMap::new();
    for e in entities.into_iter() {
        duplicates
            .entry(e.get("name").unwrap().as_str().unwrap().into())
            .and_modify(|count| *count += 1)
            .or_insert(1);
    }

    assert_eq!(duplicates.get("HSBC UK Bank plc"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK Bank PLC"), Some(&1));
    assert_eq!(duplicates.get("HSBC UK (Ian Stuart, CEO)"), Some(&1));
}

#[sqlx::test(migrations = "../db/migrations")]
async fn parliament_api_parses_all_sitting_members(pool: PgPool) -> sqlx::Result<()> {
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new().unwrap();

    let (_file, path) = cli_fetcher_config(&tmp);
    let args = DataArgs::try_parse_from([
        OsString::from("exposed-data"),
        "members".into(),
        "fetch".into(),
        path.into_os_string(),
        "--ingestion-key".into(),
        ingestion_key.to_string().into(),
    ])
    .unwrap();
    run_cli(args).await.unwrap();

    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_loader_config(&tmp);
    // The process environment must override a URL in .env.
    fs::write(tmp.path().join(".env"), "DATABASE_URL=invalid-url\n").unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(tmp.path())
        .env("DATABASE_URL", url.as_str())
        .args(["data", "members", "load"])
        .arg(path)
        .args(["--ingestion-key", &ingestion_key.to_string()])
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );

    let url = pool.connect_options().to_url_lossy();
    let db = ExposedDatabase::new(url.as_str()).await;

    let params =
        EntitySearchRequest::new_with_strictness("John McDonnell".into(), 10, 0.8).unwrap();
    let res = db.get_members_by_text_search_score(&params).await.unwrap();

    let (mp, _) = res.first().unwrap();
    assert_eq!(mp.name(), "John McDonnell".to_string());

    Ok(())
}

#[sqlx::test(migrations = "../db/migrations")]
async fn declaration_fetch_preserves_member_funding(pool: PgPool) -> anyhow::Result<()> {
    let members = sqlx::query!(
        "INSERT INTO exposed.members
            (parliament_member_id, name, party_id, party_name, latest_house,
             latest_membership_from, is_current_commons)
         VALUES (4613, 'Alex Burghart', 4, 'Conservative', 1, 'Brentwood and Ongar', true),
                (5030, 'Dr Simon Opher', 15, 'Labour', 1, 'Stroud', true)
         RETURNING id, parliament_member_id"
    )
    .fetch_all(&pool)
    .await?
    .into_iter()
    .map(|member| (member.parliament_member_id, member.id))
    .collect::<HashMap<_, _>>();
    let ingestion_key = IngestionKey::default();
    let tmp = TempDir::new()?;
    let url = pool.connect_options().to_url_lossy();
    let (_file, path) = cli_declaration_fetcher_config(&tmp);
    fs::write(tmp.path().join(".env"), format!("DATABASE_URL={url}\n"))?;
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(tmp.path())
        .env_remove("DATABASE_URL")
        .args(["data", "declarations", "fetch"])
        .arg(path)
        .args(["--ingestion-key", &ingestion_key.to_string()])
        .output()?;
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    let funding = read_declaration_funding(tmp.path(), &ingestion_key)?;

    let individual_donation = funding
        .iter()
        .find(|entry| entry.declaration_id == 16901)
        .context("expected Alex Burghart's donation from David Robert Meller")?;
    assert_eq!(
        individual_donation,
        &DeclarationFunding {
            declaration_id: 16901,
            member_id: members[&4613].to_string(),
            funding_entry: FundingEntry {
                donor_name: Some("David Robert Meller".into()),
                amount: Some("2000.00".into()),
                currency: Some("GBP".into()),
                payment_type: Some("Monetary".into()),
                funder_kind: Some("Individual".into()),
                company_number: None,
            },
        }
    );

    let company_donation = funding
        .iter()
        .find(|entry| entry.declaration_id == 16863)
        .context("expected Simon Opher's donation from Labour Together")?;
    assert_eq!(
        company_donation,
        &DeclarationFunding {
            declaration_id: 16863,
            member_id: members[&5030].to_string(),
            funding_entry: FundingEntry {
                donor_name: Some("Labour Together Limited".into()),
                amount: Some("5000.00".into()),
                currency: Some("GBP".into()),
                payment_type: Some("Monetary".into()),
                funder_kind: Some("Company".into()),
                company_number: Some("09630980".into()),
            },
        }
    );
    Ok(())
}

#[test]
fn database_commands_require_environment_url() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    // An empty .env prevents discovery of configuration from a parent directory.
    fs::write(tmp.path().join(".env"), "")?;
    let config = tmp.path().join("config.yaml");
    fs::write(
        &config,
        "data_dir: ./data\nbatch_size: 100\nconnection_string: obsolete-yaml-url\n",
    )?;

    for args in [
        ["data", "members", "load"],
        ["data", "declarations", "fetch"],
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .current_dir(tmp.path())
            .env_remove("DATABASE_URL")
            .args(args)
            .arg(&config)
            .output()?;

        assert!(!output.status.success());
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(stderr.contains("DATABASE_URL must be set"), "{stderr}");
    }
    Ok(())
}
//! CLI coverage for the latest ingestion key and path.

use std::{
    fs,
    path::Path,
    process::{Command, Output},
    time::{Duration, SystemTime},
};

use exposed::{domain::models::entity_ingestion::IngestionKey, outbound::ExposedDataPipeline};
use tempfile::TempDir;
use uuid::Uuid;

fn run_latest(root: &Path) -> anyhow::Result<Output> {
    fs::write(root.join(".env"), "")?;
    fs::write(root.join("config.yaml"), "data_dir: ./data\n")?;
    Ok(Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(root)
        .env_remove("DATABASE_URL")
        .args(["data", "latest", "config.yaml"])
        .output()?)
}

fn stdout(output: &Output) -> &str {
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    std::str::from_utf8(&output.stdout).unwrap()
}

fn create_run(data: &Path, key: &IngestionKey, seconds: u64) -> anyhow::Result<()> {
    ExposedDataPipeline::new_with_ingestion_key(&data.to_path_buf(), key.clone())?;
    fs::File::open(data.join(key.to_string()))?
        .set_modified(SystemTime::UNIX_EPOCH + Duration::from_secs(seconds))?;
    Ok(())
}

#[test]
fn reports_only_the_latest_key_and_absolute_run_path_without_a_database() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let data = tmp.path().join("data");
    let older: IngestionKey = "ffffffff-ffff-4fff-8fff-ffffffffffff".parse()?;
    let latest: IngestionKey = "00000000-0000-4000-8000-000000000001".parse()?;
    create_run(&data, &older, 10)?;
    create_run(&data, &latest, 20)?;
    fs::create_dir(data.join("not-an-ingestion-key"))?;
    fs::write(
        data.join(IngestionKey::default().to_string()),
        "not a directory",
    )?;

    let output = run_latest(tmp.path())?;
    let path = data.canonicalize()?.join(latest.to_string());

    assert_eq!(
        stdout(&output),
        format!("Ingestion key: {latest}\nPath: {}\n", path.display())
    );
    assert_eq!(fs::read_dir(&data)?.count(), 4);
    Ok(())
}

#[test]
fn equal_timestamps_use_the_greatest_uuid_regardless_of_creation_order() -> anyhow::Result<()> {
    let lower = IngestionKey::new(Uuid::from_u128(1));
    let higher = IngestionKey::new(Uuid::from_u128(2));
    for keys in [[&lower, &higher], [&higher, &lower]] {
        let tmp = TempDir::new()?;
        let data = tmp.path().join("data");
        for key in keys {
            create_run(&data, key, 10)?;
        }

        let output = run_latest(tmp.path())?;
        let path = data.canonicalize()?.join(higher.to_string());

        assert_eq!(
            stdout(&output),
            format!("Ingestion key: {higher}\nPath: {}\n", path.display())
        );
    }
    Ok(())
}

#[test]
fn missing_or_empty_store_has_no_runs_and_stays_unchanged() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let data = tmp.path().join("data");
    assert_eq!(
        stdout(&run_latest(tmp.path())?),
        "No ingestion runs found.\n"
    );
    assert!(!data.exists());

    fs::create_dir(&data)?;
    assert_eq!(
        stdout(&run_latest(tmp.path())?),
        "No ingestion runs found.\n"
    );
    assert_eq!(fs::read_dir(&data)?.count(), 0);
    Ok(())
}

#[test]
fn invalid_store_path_fails_with_a_read_error() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    fs::write(tmp.path().join("data"), "not a directory")?;

    let output = run_latest(tmp.path())?;

    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    assert!(String::from_utf8_lossy(&output.stderr).contains("unable to read pipeline data"));
    Ok(())
}
use arrow::json::ArrayWriter;
use chrono::{NaiveDate, Utc};
use exposed::{
    domain::{
        models::{
            declaration_ingestion::{
                CapturedDeclaration, CapturedFundingEntry, DeclarationId, MemberAsId,
            },
            entity_ingestion::IngestionKey,
        },
        repositories::entity_ingestion::EntityIngestionStorage,
    },
    outbound::ExposedDataPipeline,
};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use serde_json::{Value, json};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::Path,
    process::Command,
};
use uuid::Uuid;

fn rows(path: &Path) -> anyhow::Result<Vec<Value>> {
    let reader = ParquetRecordBatchReaderBuilder::try_new(fs::File::open(path)?)?.build()?;
    let mut rows = Vec::new();
    for batch in reader {
        let mut writer = ArrayWriter::new(Vec::new());
        writer.write(&batch?)?;
        writer.finish()?;
        rows.extend(serde_json::from_slice::<Vec<Value>>(&writer.into_inner())?);
    }
    Ok(rows)
}
fn run(stage: &str, config: &Path, key: &IngestionKey) -> std::process::Output {
    Command::new(env!("CARGO_BIN_EXE_exposed"))
        .args(["data", "declarations", stage])
        .arg(config)
        .arg("--ingestion-key")
        .arg(key.to_string())
        .env_remove("DATABASE_URL")
        .output()
        .unwrap()
}
#[tokio::test]
#[ignore = "requires built CLI, SQLx compile-time database, and EXPOSED_RESOLUTION_PYTHON with pinned Splink"]
async fn clean_then_resolve_with_real_splink_preserves_occurrences_and_refuses_overwrite()
-> anyhow::Result<()> {
    let python = std::env::var("EXPOSED_RESOLUTION_PYTHON")?;
    let temporary = tempfile::tempdir()?;
    let key = IngestionKey::default();
    let root = temporary.path().join("data");
    let storage = ExposedDataPipeline::new_with_ingestion_key(&root, key.clone())?;
    let member = MemberAsId::new(Uuid::from_u128(1), 1)?;
    let date = NaiveDate::from_ymd_opt(2026, 9, 7).unwrap();
    let mut captures = Vec::new();
    for id in 1..=16 {
        let (name, kind) = match id {
            1 | 2 => ("Example Charity", "Charity"),
            3..=6 => ("Gary Lubner", "Individual"),
            7 => ("HSBC UK Bank PLC", "Company"),
            8 => ("HSBC UK (Ian Stuart, CEO)", "Company"),
            9 => ("Unite Union", "Trade Union"),
            10 => ("UNITE the Union West Midlands", "Trade Union"),
            11 => ("East Midlands Unite the Union", "Trade Union"),
            12 => ("Unite the Union Parliamentary Staff Branch", "Trade Union"),
            13 => ("Northstar Consulting trading as Fletchers", "Company"),
            14 => ("Fletchers", "Company"),
            15 => ("Carlton Club", "Unincorporated association"),
            16 => (
                "Carlton Club Political Committee",
                "Unincorporated association",
            ),
            _ => unreachable!(),
        };
        let address = match id {
            1 | 2 => Some("10 Example Road, London SW1A 1AA"),
            5 => Some("20 Other Road, London SW1A 1AA"),
            6 => Some("30 Other Road, London SW1A 1AA"),
            7 => Some("1 Centenary Square, Birmingham, B1 1HQ"),
            8 => Some("1 Centenary Square Birmingham B1 1HQ"),
            15 | 16 => Some("69 St James Street, London SW1A 1PJ"),
            _ => None,
        };
        let mut fields = vec![
            json!({"name":"DonorName","value":name}),
            json!({"name":"DonorStatus","value":kind}),
            json!({"name":"Value","value":"100"}),
        ];
        if let Some(address) = address {
            fields.push(json!({"name":"DonorPublicAddress","value":address}));
        }
        let source = json!({"id":id,"category":{"id":3,"name":"Donations"},"versions":[{"register":{"id":820,"publishedDate":"2026-09-07"},"fields":fields}]});
        captures.push(CapturedDeclaration::new(
            DeclarationId::new(id)?,
            None,
            3,
            "Donations".into(),
            820,
            date,
            None,
            vec![CapturedFundingEntry::new(
                None,
                Some(name.into()),
                None,
                Some("100".into()),
                None,
                None,
                Some(kind.into()),
                None,
                None,
            )],
            Utc::now(),
            source.to_string(),
        )?);
    }
    storage.write_raw_declarations(member, &captures).await?;
    let config = temporary.path().join("resolution.yaml");
    let worker = Path::new(env!("CARGO_MANIFEST_DIR")).join("../resolution/worker.py");
    fs::write(
        &config,
        format!(
            "data_dir: {}\nresolution_python: {}\nresolution_worker: {}\ncandidate_budget: 100\n",
            serde_json::to_string(&root)?,
            serde_json::to_string(&python)?,
            serde_json::to_string(&worker)?
        ),
    )?;
    let clean = run("clean", &config, &key);
    assert!(
        clean.status.success(),
        "{}",
        String::from_utf8_lossy(&clean.stderr)
    );
    let cleaned = root.join(key.to_string()).join("cleaned/declarations");
    let before = fs::read(cleaned.join("funders.parquet"))?;
    let payments_before = fs::read(cleaned.join("funding_entries.parquet"))?;
    let funders = rows(&cleaned.join("funders.parquet"))?;
    let names = funders
        .iter()
        .map(|row| {
            (
                row["funder_id"].as_str().unwrap(),
                row["name_raw"].as_str().unwrap(),
            )
        })
        .collect::<BTreeMap<_, _>>();
    fs::remove_dir_all(root.join(key.to_string()).join("raw"))?;
    let resolved = run("resolve", &config, &key);
    assert!(
        resolved.status.success(),
        "{}",
        String::from_utf8_lossy(&resolved.stderr)
    );
    let output = root.join(key.to_string()).join("resolved/declarations");
    let observations = rows(&output.join("observation_resolution.parquet"))?;
    assert_eq!(observations.len(), 16);
    assert_eq!(
        observations
            .iter()
            .map(|r| r["identity_id"].as_str().unwrap())
            .collect::<BTreeSet<_>>()
            .len(),
        7
    );
    for (name, basis, count) in [
        ("Example Charity", "statistical_link", 2),
        ("Gary Lubner", "donor_name_link", 4),
    ] {
        let members = observations
            .iter()
            .filter(|row| names[row["funder_id"].as_str().unwrap()] == name)
            .collect::<Vec<_>>();
        assert_eq!(members.len(), count, "membership count for {name}");
        assert!(members.iter().all(|row| row["identity_basis"] == basis));
        assert_eq!(
            members
                .iter()
                .map(|row| row["identity_id"].as_str().unwrap())
                .collect::<BTreeSet<_>>()
                .len(),
            1,
            "one identity for {name}"
        );
    }
    for (prefix, basis, count) in [
        ("HSBC", "extracted_name_link", 2),
        ("Unite", "trade_union_family_link", 4),
    ] {
        let members = observations
            .iter()
            .filter(|row| {
                names[row["funder_id"].as_str().unwrap()]
                    .to_ascii_lowercase()
                    .contains(&prefix.to_ascii_lowercase())
            })
            .collect::<Vec<_>>();
        assert_eq!(members.len(), count, "membership count for {prefix}");
        assert!(members.iter().all(|row| row["identity_basis"] == basis));
        assert_eq!(
            members
                .iter()
                .map(|row| row["identity_id"].as_str().unwrap())
                .collect::<BTreeSet<_>>()
                .len(),
            1,
            "one identity for {prefix}"
        );
    }
    let alias_members = observations
        .iter()
        .filter(|row| {
            let name = names[row["funder_id"].as_str().unwrap()];
            name.contains("Northstar") || name == "Fletchers"
        })
        .collect::<Vec<_>>();
    assert_eq!(alias_members.len(), 2);
    assert!(
        alias_members
            .iter()
            .all(|row| row["identity_basis"] == "extracted_name_link")
    );
    assert_eq!(
        alias_members
            .iter()
            .map(|row| row["identity_id"].as_str().unwrap())
            .collect::<BTreeSet<_>>()
            .len(),
        1
    );
    let distinct_organizations = observations
        .iter()
        .filter(|row| names[row["funder_id"].as_str().unwrap()].starts_with("Carlton Club"))
        .collect::<Vec<_>>();
    assert_eq!(distinct_organizations.len(), 2);
    assert!(
        distinct_organizations
            .iter()
            .all(|row| row["identity_basis"] == "provisional_singleton")
    );
    assert_eq!(
        distinct_organizations
            .iter()
            .map(|row| row["identity_id"].as_str().unwrap())
            .collect::<BTreeSet<_>>()
            .len(),
        2,
        "sharing an address and organization-name root must not merge distinct organizations"
    );
    let attribution = rows(&output.join("payment_attribution.parquet"))?;
    assert_eq!(attribution.len(), 16);
    assert!(
        attribution
            .iter()
            .all(|row| row["attribution_basis"] == "donor")
    );
    let pairs = rows(&output.join("pair_decisions.parquet"))?;
    assert_eq!(pairs.len(), 16);
    let negative_pair = pairs
        .iter()
        .find(|pair| {
            names[pair["left_funder_id"].as_str().unwrap()].starts_with("Carlton Club")
                && names[pair["right_funder_id"].as_str().unwrap()].starts_with("Carlton Club")
        })
        .expect("the real worker must score the shared-address organization pair");
    assert_eq!(negative_pair["disposition"], "review");
    assert_eq!(negative_pair["reason"], "insufficient_exact_evidence");
    for pair in &pairs {
        let left_name = names[pair["left_funder_id"].as_str().unwrap()];
        let right_name = names[pair["right_funder_id"].as_str().unwrap()];
        if left_name.starts_with("Carlton Club") {
            assert_ne!(left_name, right_name);
            assert_eq!(pair["disposition"], "review");
            continue;
        }
        assert_eq!(pair["disposition"], "accepted");
        if left_name == "Gary Lubner" {
            assert_eq!(left_name, right_name);
            assert_eq!(pair["reason"], "exact_donor_name");
            assert!(pair["probability"].as_f64().unwrap() < 0.999);
            assert!(pair["probability"].as_f64().unwrap() > 0.0);
        } else if left_name.contains("HSBC") || right_name.contains("HSBC") {
            assert_eq!(pair["reason"], "extracted_name_evidence");
        } else if left_name.contains("Unite") || right_name.contains("Unite") {
            assert_eq!(pair["reason"], "trade_union_family");
        } else if left_name.contains("Northstar") || right_name.contains("Northstar") {
            assert_eq!(pair["reason"], "extracted_name_evidence");
        } else {
            assert_eq!(left_name, right_name);
            assert_eq!(pair["reason"], "exact_name_full_address_threshold");
        }
    }
    let manifest = fs::read(output.join("manifest.json"))?;
    let model: Value = serde_json::from_slice(&manifest)?;
    assert_eq!(model["model"]["splink_version"], "4.0.17");
    assert_eq!(model["model"]["calibrated"], false);
    assert_eq!(model["policy_version"], "funder-resolution-v3");
    assert_eq!(fs::read(cleaned.join("funders.parquet"))?, before);
    assert_eq!(
        fs::read(cleaned.join("funding_entries.parquet"))?,
        payments_before
    );
    assert!(!run("resolve", &config, &key).status.success());
    assert_eq!(fs::read(output.join("manifest.json"))?, manifest);
    Ok(())
}

