                assert!(read_table(&cleaned_path(tmp.path(), &key).join(table))?.is_empty());
            }
        } else {
            assert!(!output.status.success());
            assert!(String::from_utf8_lossy(&output.stderr).contains("schema"));
            assert!(!cleaned_path(tmp.path(), &key).exists());
        }
    }
    Ok(())
}

