) -> (
    Fake,
    mpsc::UnboundedReceiver<u32>,
    mpsc::UnboundedReceiver<u32>,
) {
    let (started, starts) = mpsc::unbounded_channel();
    let (writes, saved) = mpsc::unbounded_channel();
    (
        Fake {
            members: (1..=count)
                .map(|id| MemberAsId::new(Uuid::now_v7(), id).unwrap())
                .collect(),
            key: IngestionKey::default(),
            started,
            writes,
            permits: Arc::new(Semaphore::new(0)),
            fail: false,
        },
        starts,
        saved,
    )
}

async fn receive(receiver: &mut mpsc::UnboundedReceiver<u32>) -> u32 {
    tokio::time::timeout(Duration::from_secs(5), receiver.recv())
        .await
        .unwrap()
        .unwrap()
}

#[tokio::test]
async fn keeps_ten_members_active_through_storage_and_refills_each_slot() {
    let (fake, mut starts, mut saved) = fixture(23);
    let service = DeclarationFetcherService::new(fake.clone(), fake.clone(), fake.clone());
    let run = tokio::spawn(async move { service.fetch_declarations().await });
    for _ in 0..10 {
        receive(&mut starts).await;
    }
    assert!(
        tokio::time::timeout(Duration::from_millis(50), starts.recv())
            .await
            .is_err()
    );
    fake.permits.add_permits(1);
    let first_saved = receive(&mut saved).await;
    assert_eq!(receive(&mut starts).await, 11);
    assert!(
        tokio::time::timeout(Duration::from_millis(50), starts.recv())
            .await
            .is_err()
    );
    fake.permits.add_permits(22);
    assert_eq!(run.await.unwrap().unwrap(), fake.key);
    let mut written = vec![first_saved];
    while let Ok(id) = saved.try_recv() {
        written.push(id);
    }
    assert_eq!(written.len(), 23);
    written.sort_unstable();
    written.dedup();
    assert_eq!(written.len(), 23);
}

#[tokio::test]
async fn storage_failure_cancels_pending_members_without_scheduling_more() {
    let (mut fake, mut starts, mut saved) = fixture(23);
    fake.fail = true;
    let service = DeclarationFetcherService::new(fake.clone(), fake.clone(), fake.clone());
    let run = tokio::spawn(async move { service.fetch_declarations().await });
    for _ in 0..10 {
        receive(&mut starts).await;
    }
    fake.permits.add_permits(1);
    let result = tokio::time::timeout(Duration::from_secs(5), run)
        .await
        .unwrap()
        .unwrap();
    assert!(matches!(result, Err(EntityIngestionError::IoError(_))));
    assert!(starts.try_recv().is_err());
    assert!(saved.try_recv().is_err());
    assert_eq!(Arc::strong_count(&fake.permits), 1);
}

#[tokio::test]
async fn rejects_empty_cohort_without_starting_tasks() {
    let (fake, mut starts, _) = fixture(0);
    let service = DeclarationFetcherService::new(fake.clone(), fake.clone(), fake);
    assert!(matches!(
        service.fetch_declarations().await,
        Err(EntityIngestionError::DataError(_))
    ));
    assert!(starts.try_recv().is_err());
}
//! Entity search refers to the landing page of the `exposed` application. Its purpose it to make it
//! easy for journalists to find [`parliament_members`] or [`funders`].
//!

mod error;
mod interface;

use crate::domain::models::entity_search::{Entity, EntitySearchError, EntitySearchRequest};
use crate::domain::models::funder::Funder;
use crate::domain::models::parliament_member::ParliamentMember;
use crate::domain::models::search_similarity::SearchSimilarity;
use crate::domain::repositories::funder_repository::FunderRepo;
use crate::domain::repositories::parliament_member_repository::ParliamentMemberRepo;
pub use crate::domain::services::entity_search::interface::EntitySearchService;

/// Allows users to search the databse using free text.
#[derive(Clone)]
pub struct Service<P, F> {
    mp_repo: P,
    funder_repo: F,
}

impl<P, F> Service<P, F> {
    /// Creates a new instance
    pub const fn new(mp_repo: P, funder_repo: F) -> Self {
        Self {
            mp_repo,
            funder_repo,
        }
    }
}

impl<P, F> EntitySearchService for Service<P, F>
where
    P: ParliamentMemberRepo,
    F: FunderRepo,
{
    /// Returns text search results for MPs and Funder entities.
    ///
    /// This function expects the repositories to return their results
    /// in order where a higher score means a higher similarity.
    async fn search_entities(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<Entity>, EntitySearchError> {
        let mps = self.mp_repo.get_members_by_text_search_score(req).await?;
        let funders = self
            .funder_repo
            .get_funders_by_text_search_score(req)
            .await?;

        let scored = merge_scores(&mps, &funders);
        Ok(scored)
    }
}

/// Uses two-pointer technique to merge to pre-sorted
/// search results together.
fn merge_scores(
    mps: &[(ParliamentMember, SearchSimilarity)],
    funders: &[(Funder, SearchSimilarity)],
) -> Vec<Entity> {
    let mut scores = Vec::new();

    let (mut l, mut r) = (0, 0);
    // Unwrap acceptable as index check in
    // while function
    while l < mps.len() && r < funders.len() {
        let mp: &(ParliamentMember, SearchSimilarity) = mps.get(l).unwrap();
        let fund: &(Funder, SearchSimilarity) = funders.get(r).unwrap();

        match &mp.1.value().total_cmp(&fund.1.value()) {
            std::cmp::Ordering::Equal => {
                scores.push(Entity::from(&mp.0));
                scores.push(Entity::from(&fund.0));
                l += 1;
                r += 1;
            }
            std::cmp::Ordering::Greater => {
                scores.push(Entity::from(&mp.0));
                l += 1;
            }
            std::cmp::Ordering::Less => {
                scores.push(Entity::from(&fund.0));
                r += 1;
            }
        }
    }
    if l < mps.len() {
        for mp in &mps[l..] {
            scores.push(Entity::from(&mp.0));
        }
    }
    if r < funders.len() {
        for fund in &funders[r..] {
            scores.push(Entity::from(&fund.0));
        }
    }

    scores
}

